sys_script.script:
if( JSUtil.nil(current.project) || current.project == 'NULL' ) {
	current.setValue('project_phase', '');
}else if(!(current.project_phase.changes() && JSUtil.nil(current.project_phase))){
	//Update phase only if they are not removing phase of story
	if(JSUtil.nil(current.project_phase) || current.project_phase == 'NULL' || (current.project.changes() && current.project_phase.parent != current.project)){
		var projectUtil = new ppm_int_ProjectUtil(current.project.sys_id);
		var phases = projectUtil.getDevelopmentPhases();
		if(phases.getRowCount() == 1 && phases.next()){
			current.project_phase = phases.sys_id;
		}else{
			current.setValue('project_phase', '');
		}
	}

	if(JSUtil.notNil(current.project_phase) && current.project_phase != 'NULL' && JSUtil.nil(current.getValue('assignment_group')) && JSUtil.notNil(current.project_phase.assignment_group)){
		var team = current.project_phase.assignment_group;
		current.setValue('assignment_group', team);
	}
}
